impl LatestReleaseInfo {
    pub fn matching_asset(&self, os: &str, arch: &str) -> Option<&ReleaseAssetInfo> {
        self.assets
            .iter()
            .find(|asset| asset.platform == os && asset.arch == normalize_arch(arch))
    }
