// ── Storage ───────────────────────────────────────────────────────────────────

impl Default for ChatStorage {
    fn default() -> Self {
        let random_id: u32 = rand::random();
        let path = std::env::temp_dir().join(format!("llama_monitor_test_{}.db", random_id));
