        let guard = self.conn.lock().unwrap();
        let conn = guard.as_ref().expect("db open");
        let tx = conn.unchecked_transaction()?;
        for (i, id) in ordered_ids.iter().enumerate() {
            tx.execute(
                "UPDATE tabs SET tab_order = ?1 WHERE id = ?2",
