                    created_at: row.get(19)?,
                    updated_at: row.get(20)?,
                    visibility: row.get(21)?,
                    composer_draft: row.get(22)?,
                    ai_gender: row.get(23)?,
                    template_version_or_hash: row.get(24)?,
