        )?;

        let notes_count = match &tab.context_notes {
            serde_json::Value::Array(arr) => arr.len() as i64,
            _ => 0,
        };

        Ok(TabMeta {
            id: tab.id,
            name: tab.name,
            explicit_level: tab.explicit_level,
            active_template_id: tab.active_template_id,
